"use client";

import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { motion } from "framer-motion";

export default function Contact() {
  return (
    <section id="contact" className="py-32 bg-zinc-950 border-t border-zinc-900 relative overflow-hidden">
      {/* Animation Background - Moving Grid */}
      <div className="absolute inset-0 opacity-20 pointer-events-none">
        <div className="absolute inset-0 bg-[linear-gradient(to_right,#22d3ee08_1px,transparent_1px),linear-gradient(to_bottom,#22d3ee08_1px,transparent_1px)] bg-[size:40px_40px] [mask-image:radial-gradient(ellipse_60%_60%_at_50%_50%,#000_10%,transparent_100%)]" />
        <motion.div
          animate={{ backgroundPosition: ["0px 0px", "40px 40px"] }}
          transition={{ duration: 4, repeat: Infinity, ease: "linear" }}
          className="absolute inset-0 bg-[linear-gradient(to_right,#22d3ee15_1px,transparent_1px),linear-gradient(to_bottom,#22d3ee15_1px,transparent_1px)] bg-[size:40px_40px]"
        />
      </div>

      <div className="container-width relative z-10">
        <div className="grid lg:grid-cols-2 gap-12 items-center">
          {/* Text Content */}
          <div className="max-w-2xl">
            <h2 className="text-5xl md:text-7xl font-bold tracking-tighter text-white mb-8 leading-[0.9]">
              Ready to ship?
            </h2>
            <p className="text-xl md:text-2xl text-zinc-400 font-light mb-12 tracking-tight">
              From concept to production — without friction.
            </p>

            <div className="flex flex-col sm:flex-row gap-6">
              <Link
                href="mailto:hello@oryxen.com"
                className="bg-white text-black px-8 py-4 text-lg font-bold rounded-md hover:bg-zinc-200 transition-colors inline-flex items-center gap-3 w-fit"
              >
                Start specific project
                <ArrowRight className="w-5 h-5" />
              </Link>
              <Link
                href="mailto:hello@oryxen.com"
                className="px-8 py-4 text-lg font-medium text-zinc-400 hover:text-white transition-colors border border-zinc-800 rounded-md w-fit"
              >
                Book a consultation
              </Link>
            </div>
          </div>

          {/* Right Side: Flow/Pipeline Animation */}
          <div className="relative h-[400px] w-full hidden lg:block">
            {/* Visual Container */}
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="relative w-full h-full max-w-lg">

                {/* Connecting Lines (svg) */}
                <svg className="absolute inset-0 w-full h-full" style={{ overflow: 'visible' }}>
                  <title>Pipeline Flow</title>
                  <defs>
                    <linearGradient id="gradientLine" x1="0%" y1="0%" x2="100%" y2="0%">
                      <stop offset="0%" stopColor="rgba(34, 211, 238, 0)" />
                      <stop offset="50%" stopColor="rgba(34, 211, 238, 0.5)" />
                      <stop offset="100%" stopColor="rgba(34, 211, 238, 0)" />
                    </linearGradient>
                  </defs>

                  {/* Paths */}
                  <path d="M50 200 C 150 200, 150 100, 250 100" fill="none" stroke="#333" strokeWidth="2" />
                  <path d="M50 200 C 150 200, 150 300, 250 300" fill="none" stroke="#333" strokeWidth="2" />
                  <path d="M250 100 L 350 100" fill="none" stroke="#333" strokeWidth="2" />
                  <path d="M250 300 L 350 300" fill="none" stroke="#333" strokeWidth="2" />
                  <path d="M350 100 C 400 100, 400 200, 450 200" fill="none" stroke="#333" strokeWidth="2" />
                  <path d="M350 300 C 400 300, 400 200, 450 200" fill="none" stroke="#333" strokeWidth="2" />

                  {/* Animated Particles */}
                  <circle r="4" fill="#22d3ee">
                    <animateMotion dur="3s" repeatCount="indefinite" path="M50 200 C 150 200, 150 100, 250 100 L 350 100 C 400 100, 400 200, 450 200" />
                  </circle>
                  <circle r="4" fill="#22d3ee">
                    <animateMotion dur="3s" begin="1.5s" repeatCount="indefinite" path="M50 200 C 150 200, 150 300, 250 300 L 350 300 C 400 300, 400 200, 450 200" />
                  </circle>
                </svg>

                {/* Nodes */}
                <motion.div
                  initial={{ opacity: 0.5 }} animate={{ opacity: [0.5, 1, 0.5] }} transition={{ duration: 2, repeat: Infinity }}
                  className="absolute left-[30px] top-[180px] w-10 h-10 bg-zinc-900 border border-zinc-700 rounded-full flex items-center justify-center z-10"
                >
                  <div className="w-2 h-2 bg-zinc-500 rounded-full" />
                </motion.div>

                <div className="absolute left-[230px] top-[80px] w-12 h-12 bg-zinc-900 border border-zinc-700 rounded-md flex items-center justify-center z-10">
                  <div className="w-6 h-1 bg-zinc-800 rounded-sm mb-1" />
                  <div className="w-4 h-1 bg-zinc-800 rounded-sm" />
                </div>

                <div className="absolute left-[230px] top-[280px] w-12 h-12 bg-zinc-900 border border-zinc-700 rounded-md flex items-center justify-center z-10">
                  <div className="w-4 h-4 border-2 border-zinc-800 rounded-full" />
                </div>

                <motion.div
                  initial={{ scale: 1 }} animate={{ scale: [1, 1.1, 1] }} transition={{ duration: 1.5, repeat: Infinity }}
                  className="absolute right-[30px] top-[180px] w-14 h-14 bg-zinc-950 border border-cyan-900/50 shadow-[0_0_20px_rgba(34,211,238,0.2)] rounded-lg flex items-center justify-center z-10"
                >
                  <div className="w-3 h-3 bg-cyan-500 rounded-full" />
                </motion.div>

              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
