"use client";

import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { motion } from "framer-motion";
import CodeEditor from "./ui/CodeEditor";

export default function Hero() {
  return (
    <section className="relative min-h-[90vh] flex items-center bg-black pt-32 pb-20 overflow-hidden border-b border-zinc-900">

      {/* Subtle Animated Background */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_80%_50%_at_50%_-20%,rgba(120,119,198,0.1),rgba(255,255,255,0))]" />
      <div className="absolute inset-0 z-0">
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 0.1 }}
          transition={{ duration: 2 }}
          className="absolute inset-0 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px]"
        />
      </div>

      <div className="container-width relative z-10">
        <div className="grid lg:grid-cols-2 gap-12 lg:gap-20 items-center">

          {/* Text Content */}
          <div className="relative z-20 text-center lg:text-left flex flex-col justify-center"> {/* Removed strict height to fix alignment */}
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
              className="flex flex-col justify-center h-full"
            >
              <div className="hidden" />

              <h1 className="text-5xl sm:text-7xl font-bold tracking-tighter text-white mb-6 leading-[0.95] min-h-[2.85em] lg:h-auto flex flex-col justify-end"> {/* Hard lock min-height */}
                We build digital <br />
                <span className="text-zinc-500">systems</span> for <br />
                what's next.
              </h1>

              <p className="text-lg sm:text-xl text-zinc-400 max-w-xl mx-auto lg:mx-0 leading-relaxed mb-10 font-light min-h-[3.5em] flex flex-col justify-start"> {/* Hard lock min-height */}
                ORYXEN designs and develops websites, applications, platforms, and intelligent software for founders and companies worldwide.
              </p>

              <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start">
                <Link
                  href="#contact"
                  className="bg-white text-black px-8 py-4 text-base font-bold rounded-md hover:bg-zinc-200 transition-colors flex items-center justify-center gap-2"
                >
                  Start a Project
                  <ArrowRight className="w-4 h-4" />
                </Link>
                <Link
                  href="#services"
                  className="text-zinc-400 hover:text-white px-8 py-4 text-base font-medium transition-colors border-2 border-transparent hover:border-zinc-800 rounded-md flex items-center justify-center"
                >
                  View Work
                </Link>
              </div>
            </motion.div>
          </div>

          {/* Visual Content - Live Code Editor */}
          <div className="w-full flex items-center justify-center lg:justify-end"> {/* Removed strict height */}
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ duration: 0.5, delay: 0.2 }}
              className="w-full"
            >
              <CodeEditor />
            </motion.div>
          </div>

        </div>
      </div>
    </section>
  );
}
