"use client";

import { motion } from "framer-motion";

export default function Products() {
  return (
    <section id="products" className="py-32 bg-zinc-950 border-b border-zinc-900 overflow-hidden">
      <div className="container-width">
        <div className="grid lg:grid-cols-2 gap-16 lg:gap-24 items-center">

          {/* New Copy: Internal Systems Focus */}
          <div>
            <div className="mb-8">
              <span className="text-xs font-mono text-cyan-500 uppercase tracking-widest bg-cyan-950/30 px-3 py-1.5 rounded-sm border border-cyan-900/50">
                System Architecture
              </span>
            </div>
            <h2 className="text-4xl md:text-5xl font-bold text-white mb-6 tracking-tight leading-tight">
              Modular by design. <br /> Precision engineered.
            </h2>
            <p className="text-zinc-400 text-lg leading-relaxed mb-8">
              We focus on carefully designed systems and production-grade workflows. Our architecture is built on well-integrated tools and proven patterns, ensuring scalability without unnecessary complexity.
            </p>
          </div>

          {/* System Diagram Visual: Complex Infrastructure Animation */}
          <div className="lg:w-full relative h-[400px] bg-black/50 rounded-xl border border-zinc-800 overflow-hidden flex items-center justify-center">

            {/* Background Grid */}
            <div className="absolute inset-0 bg-[linear-gradient(to_right,#22d3ee05_1px,transparent_1px),linear-gradient(to_bottom,#22d3ee05_1px,transparent_1px)] bg-[size:20px_20px]" />

            {/* Main schematic container */}
            <div className="relative w-full h-full p-8 flex items-center justify-center">

              <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                <defs>
                  <linearGradient id="traceGradient" x1="0" y1="0" x2="1" y2="0">
                    <stop offset="0%" stopColor="#22d3ee" stopOpacity="0" />
                    <stop offset="50%" stopColor="#22d3ee" stopOpacity="1" />
                    <stop offset="100%" stopColor="#22d3ee" stopOpacity="0" />
                  </linearGradient>
                  <filter id="glow">
                    <feGaussianBlur stdDeviation="2" result="coloredBlur" />
                    <feMerge>
                      <feMergeNode in="coloredBlur" />
                      <feMergeNode in="SourceGraphic" />
                    </feMerge>
                  </filter>
                </defs>

                {/* Connection Lines */}
                {/* Left to Center */}
                <path d="M100 200 L 250 200" stroke="#333" strokeWidth="1" />
                {/* Center to Top Right */}
                <path d="M350 200 C 400 200, 400 120, 450 120" stroke="#333" strokeWidth="1" fill="none" />
                {/* Center to Bottom Right */}
                <path d="M350 200 C 400 200, 400 280, 450 280" stroke="#333" strokeWidth="1" fill="none" />

                {/* Data Packets */}
                <rect width="8" height="2" fill="#22d3ee" filter="url(#glow)">
                  <animateMotion dur="2s" repeatCount="indefinite" path="M100 200 L 250 200" />
                </rect>

                {/* Branching Packets */}
                <circle r="3" fill="#22d3ee" filter="url(#glow)">
                  <animateMotion dur="2s" begin="0.5s" repeatCount="indefinite" path="M350 200 C 400 200, 400 120, 450 120" />
                </circle>
                <circle r="3" fill="#22d3ee" filter="url(#glow)">
                  <animateMotion dur="2s" begin="1s" repeatCount="indefinite" path="M350 200 C 400 200, 400 280, 450 280" />
                </circle>
              </svg>

              {/* Left Node: Ingestion */}
              <motion.div
                className="absolute left-[50px] top-1/2 -translate-y-1/2 w-16 h-16 bg-zinc-900 border border-zinc-700 rounded-md flex flex-col items-center justify-center z-10"
                initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} transition={{ delay: 0.2 }}
              >
                <div className="w-8 h-1 bg-zinc-700 rounded-full mb-1" />
                <div className="w-6 h-1 bg-zinc-700 rounded-full mb-1" />
                <div className="w-8 h-1 bg-zinc-700 rounded-full" />
              </motion.div>

              {/* Center Node: Processing Core */}
              <motion.div
                className="absolute left-1/2 -translate-x-1/2 top-1/2 -translate-y-1/2 w-32 h-32 bg-zinc-950 border border-cyan-900/40 rounded-lg flex flex-col items-center justify-center z-20 shadow-[0_0_30px_-5px_rgba(34,211,238,0.1)]"
                initial={{ scale: 0.9, opacity: 0 }} whileInView={{ scale: 1, opacity: 1 }} transition={{ delay: 0.4 }}
              >
                {/* Inner Activity Animation */}
                <div className="grid grid-cols-3 gap-1 w-16 h-16">
                  {[...Array(9)].map((_, i) => (
                    <motion.div
                      key={i}
                      className="bg-cyan-900/30 rounded-sm"
                      animate={{ backgroundColor: ["rgba(22,78,99,0.3)", "rgba(34,211,238,0.5)", "rgba(22,78,99,0.3)"] }}
                      transition={{ duration: 1.5, repeat: Infinity, delay: i * 0.1 }}
                    />
                  ))}
                </div>
                <div className="absolute -bottom-6 text-[10px] font-mono text-cyan-500/70 tracking-widest">PROCESSING</div>
              </motion.div>

              {/* Right Top Node: Storage/Output */}
              <motion.div
                className="absolute right-[50px] top-[100px] w-14 h-14 bg-zinc-900 border border-zinc-700 rounded-md flex items-center justify-center z-10"
                initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} transition={{ delay: 0.6 }}
              >
                <div className="w-6 h-6 border-2 border-zinc-600 rounded-full" />
              </motion.div>

              {/* Right Bottom Node: API/Output */}
              <motion.div
                className="absolute right-[50px] top-[260px] w-14 h-14 bg-zinc-900 border border-zinc-700 rounded-md flex items-center justify-center z-10"
                initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} transition={{ delay: 0.7 }}
              >
                <div className="text-[10px] font-mono text-zinc-500">API</div>
              </motion.div>

            </div>
          </div>

        </div>
      </div>
    </section>
  );
}
