"use client";

import { useFormStatus } from "react-dom";
import { sendContactEmail } from "@/app/actions";
import { Mail, Globe, ArrowRight, Loader2 } from "lucide-react";
import { useState } from "react";

function SubmitButton() {
  const { pending } = useFormStatus();

  return (
    <button
      type="submit"
      disabled={pending}
      className="ml-auto flex items-center gap-2 bg-white text-black px-8 py-3 rounded-md font-medium hover:bg-zinc-200 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
    >
      {pending ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
      {pending ? "Sending..." : "Send Message"}
    </button>
  );
}

export default function Collaborate() {
  const [success, setSuccess] = useState(false);

  async function clientAction(formData: FormData) {
    const result = await sendContactEmail(formData);
    if (result.success) {
      setSuccess(true);
    } else {
      alert("Something went wrong. Please try again.");
    }
  }

  return (
    <section id="collaborate" className="py-32 bg-zinc-950 border-t border-zinc-900 border-b">
      <div className="container-width">

        {/* Header */}
        <div className="mb-16">
          <div className="inline-block px-3 py-1 mb-6 rounded-full border border-cyan-900/50 bg-cyan-950/10">
            <span className="text-xs font-mono text-cyan-400 uppercase tracking-widest">Contact</span>
          </div>
          <h2 className="text-5xl md:text-6xl font-bold tracking-tighter text-white mb-6">
            Let's Build Together
          </h2>
          <p className="text-xl text-zinc-400 font-light max-w-2xl">
            Ready to start your project? Get in touch and let's discuss how Oryxen can help bring your vision to life.
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-16 lg:gap-24">

          {/* Left Column: Contact Info */}
          <div className="space-y-8">
            <div className="p-6 rounded-lg bg-zinc-900/30 border border-zinc-800/50 flex items-start gap-4">
              <div className="p-3 bg-zinc-900 rounded-md">
                <Mail className="w-6 h-6 text-cyan-500" />
              </div>
              <div>
                <h3 className="text-sm font-medium text-zinc-500 mb-1">Email</h3>
                <a href="mailto:hello@oryxen.tech" className="text-lg font-medium text-white hover:text-cyan-400 transition-colors">
                  hello@oryxen.tech
                </a>
              </div>
            </div>

            <div className="p-6 rounded-lg bg-zinc-900/30 border border-zinc-800/50 flex items-start gap-4">
              <div className="p-3 bg-zinc-900 rounded-md">
                <Globe className="w-6 h-6 text-cyan-500" />
              </div>
              <div>
                <h3 className="text-sm font-medium text-zinc-500 mb-1">Location</h3>
                <p className="text-lg font-medium text-white">
                  Global Remote Team
                </p>
              </div>
            </div>
          </div>

          {/* Right Column: Form */}
          <div className="bg-zinc-900/10 p-1 rounded-xl">
            {success ? (
              <div className="h-full min-h-[400px] flex flex-col items-center justify-center text-center p-8 bg-zinc-900/20 rounded-lg border border-zinc-800 border-dashed">
                <div className="w-16 h-16 bg-green-500/10 rounded-full flex items-center justify-center mb-6">
                  <ArrowRight className="w-8 h-8 text-green-500" /> {/* Check icon would be better but reusing import */}
                </div>
                <h3 className="text-2xl font-bold text-white mb-2">Message Sent</h3>
                <p className="text-zinc-400">Thanks for reaching out. We'll be in touch shortly.</p>
                <button onClick={() => setSuccess(false)} className="mt-8 text-sm text-zinc-500 underline hover:text-white">
                  Send another message
                </button>
              </div>
            ) : (
              <form action={clientAction} className="space-y-6">
                {/* Name */}
                <div className="space-y-2">
                  <label htmlFor="name" className="text-sm font-medium text-zinc-300">Name *</label>
                  <input
                    required
                    name="name"
                    id="name"
                    type="text"
                    placeholder="Your name"
                    className="w-full bg-zinc-900/50 border border-zinc-800 rounded-md px-4 py-3 text-white placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-cyan-500/20 focus:border-cyan-500/50 transition-all"
                  />
                </div>

                {/* Email */}
                <div className="space-y-2">
                  <label htmlFor="email" className="text-sm font-medium text-zinc-300">Email *</label>
                  <input
                    required
                    name="email"
                    id="email"
                    type="email"
                    placeholder="you@company.com"
                    className="w-full bg-zinc-900/50 border border-zinc-800 rounded-md px-4 py-3 text-white placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-cyan-500/20 focus:border-cyan-500/50 transition-all"
                  />
                </div>

                {/* Company */}
                <div className="space-y-2">
                  <label htmlFor="company" className="text-sm font-medium text-zinc-300">Company (optional)</label>
                  <input
                    name="company"
                    id="company"
                    type="text"
                    placeholder="Your company"
                    className="w-full bg-zinc-900/50 border border-zinc-800 rounded-md px-4 py-3 text-white placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-cyan-500/20 focus:border-cyan-500/50 transition-all"
                  />
                </div>

                {/* Description */}
                <div className="space-y-2">
                  <label htmlFor="description" className="text-sm font-medium text-zinc-300">Project Description *</label>
                  <textarea
                    required
                    name="description"
                    id="description"
                    rows={5}
                    placeholder="Tell us about your project..."
                    className="w-full bg-zinc-900/50 border border-zinc-800 rounded-md px-4 py-3 text-white placeholder:text-zinc-600 focus:outline-none focus:ring-2 focus:ring-cyan-500/20 focus:border-cyan-500/50 transition-all resize-none"
                  />
                </div>

                <div className="pt-2 flex">
                  <SubmitButton />
                </div>
              </form>
            )}
          </div>

        </div>
      </div>
    </section>
  );
}
